package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.AppUser; import com.example.smartexpenseanalyzer.repository.AppUserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.Optional; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.security.core.userdetails.UsernameNotFoundException;
@Service public class AppUserDetailsService implements UserDetailsService { private final AppUserRepository users; private final PasswordEncoder encoder; public AppUserDetailsService(AppUserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;} public Optional<AppUser> register(String name,String email,String rawPassword){if(users.findByEmailIgnoreCase(email).isPresent())return Optional.empty();AppUser u=new AppUser();u.name=name;u.email=email;u.passwordHash=encoder.encode(rawPassword);u.role="USER";return Optional.of(users.save(u));} public Optional<AppUser> authenticate(String email,String rawPassword){return users.findByEmailIgnoreCase(email).filter(u->encoder.matches(rawPassword,u.passwordHash));} @Override public UserDetails loadUserByUsername(String email){AppUser u=users.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Account not found"));return org.springframework.security.core.userdetails.User.withUsername(u.email).password(u.passwordHash).roles(u.role).build();} public Optional<AppUser> find(Long id){return users.findById(id);} public java.util.List<AppUser> all(){return users.findAll();} public AppUser save(AppUser u){return users.save(u);} public void delete(AppUser u){users.delete(u);} }
